{"witnessCode": "import { describe, it } from 'node:test';
import assert from 'node:assert/strict';
import normalizeUrl from '../index.js';

describe('keepQueryParameters empty array regression', () => {
  it('should keep query parameters when keepQueryParameters is an empty array', () => {
    const url = 'https://example.com/path?foo=bar&baz=qux';
    const options = { keepQueryParameters: [] };
    const expected = 'https://example.com/path?baz=qux&foo=bar';
    const actual = normalizeUrl(url, options);
    assert.strictEqual(actual, expected);
  });
});"}
